    /// </summary>
    [TestMethod]
    public void FromUnixTimeMilliseconds_WhenAboveMaximum_ShouldThrowExactly()
    {
        long aboveMax = 253402300800000; // 1 ms after DateOnly.MaxValue

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
