    public void FromUnixTimeMilliseconds_WhenBelowMinimum_ShouldThrowExactly()
    {
        long belowMin = -62135596800001; // 1 ms before DateOnly.MinValue

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
